```cpp
#include <string>
#include <regex>

std::string convertToHtml(const std::string& text_in_emphasis) {
    // Регулярный выражение для поиска текста в уценке
    std::regex regex_emphasis(R"(\b(\*|_)\w+(\*|_)\b)");

    // Замена текста в уценке на HTML теги
    std::string text_in_html;
    std::smatch match;
    while (std::regex_search(text_in_emphasis, match, regex_emphasis)) {
        std::string emphasis_text = match.str(1);
        std::string html_tag;
        if (emphasis_text.find('*') != stdstd::string::npos) {
            html_tag = "<strong>";
        } else if (emphasis_text.find('_') != std::string::npos) {
            html_tag = "<em>";
        }
        text_in_html += html_tag + emphasis_text + "</" + html_tag + ">";
        text_in_emphasis = match.prefix();
    }

    return text_in_html;
}
```

